 "content": "def transform(grid):
    """Copy the distinctive non-background shape into every all-zero matching location."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 1)}
    if not colors:
        return out
    color = next(iter(colors))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    # Use the entire colored figure as a template, normalized to its top-left.
    r0 = min(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh = max(r for r, _ in shape) + 1
    sw = max(c for _, c in shape) + 1
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if (r, c) == (r0, c0):
                continue
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out

if __name__ == '__main__':
